import React from 'react';
import { Avatar } from '@arco-design/web-react';
import { Select, FormItem, FormButtonGroup, Submit } from '@storage-fe/formily-arco';
import { createForm, onFieldReact, onFieldInit, FormPathPattern, Field } from '@formily/core';
import { FormProvider, createSchemaField } from '@formily/react';
import { action, observable } from '@formily/reactive';
import { debounce } from 'lodash';

let refFetchId = Date.now();

const debouncedFetchUser = debounce((_: string, callback: any) => {
  refFetchId = Date.now();
  const fetchId = refFetchId;
  fetch('https://randomuser.me/api/?results=5')
    .then(response => response.json())
    .then(body => {
      if (refFetchId === fetchId) {
        const options = body.results.map((user: any) => ({
          label: (
            <div style={{ display: 'flex', alignItems: 'center' }}>
              <Avatar size={24} style={{ marginLeft: 6, marginRight: 12 }}>
                <img alt="avatar" src={user.picture.thumbnail} />
              </Avatar>
              {`${user.name.first} ${user.name.last}`}
            </div>
          ),
          value: user.email,
        }));
        callback(options);
      }
    });
}, 500);

const SchemaField = createSchemaField({
  components: {
    Select,
    FormItem,
  },
});

const AsyncDataSourceEffect = (
  pattern: FormPathPattern,
  service: (param: { keyword: string; field: Field }) => Promise<{ label: string; value: any }[]>
) => {
  const keyword = observable.ref('');

  onFieldInit(pattern, field => {
    field.setComponentProps({
      onSearch: (value: string) => {
        keyword.value = value;
      },
    });
  });

  onFieldReact(pattern, field => {
    const _field = field as Field;
    _field.loading = true;
    service({ field: _field, keyword: keyword.value }).then(
      action.bound?.(data => {
        _field.dataSource = data;
        _field.loading = false;
      })
    );
  });
};

const form = createForm({
  effects: () => {
    AsyncDataSourceEffect('select', async ({ keyword }) => {
      if (!keyword) {
        return [];
      }
      return new Promise(resolve => {
        debouncedFetchUser(keyword, resolve);
      });
    });
  },
});

export default () => (
  <FormProvider form={form}>
    <SchemaField>
      <SchemaField.String
        name="select"
        title="异步搜索选择框"
        x-decorator="FormItem"
        x-component="Select"
        x-component-props={{
          showSearch: true,
          filterOption: false,
          style: {
            width: 300,
          },
        }}
      />
    </SchemaField>
    <FormButtonGroup>
      <Submit onSubmit={console.log}>提交</Submit>
    </FormButtonGroup>
  </FormProvider>
);
